import Link from "next/link";
import { requireVendor } from "@/lib/dal";
import { prisma } from "@/lib/prisma";
import { createVendorProduct } from "@/lib/vendor/product-actions";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

export default async function CreateVendorProductPage() {
  await requireVendor();
  const categories = await prisma.productCategory.findMany({ where: { isActive: true, parentId: null }, orderBy: { sortOrder: "asc" }, select: { id: true, name: true } });
  return <main className="mx-auto flex max-w-5xl flex-col gap-6"><div><p className="text-sm text-muted-foreground">Vendor catalog</p><h1 className="text-3xl font-semibold">Create a product</h1><p className="mt-2 text-muted-foreground">Products are reviewed before they become visible in the marketplace.</p></div><form action={createVendorProduct} className="flex flex-col gap-6"><Card><CardHeader><CardTitle>Basic information</CardTitle></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><Field name="name" label="Product name *" required /><Field name="slug" label="Slug" placeholder="Auto-generated if empty" /><Field name="brand" label="Brand" /><Field name="categoryId" label="Category *" required select options={categories.map((c) => ({ value: c.id, label: c.name }))} /><Field name="subcategory" label="Subcategory" /><Field name="price" label="Price (₹) *" type="number" required /><Field name="mrp" label="MRP (₹)" type="number" /><Field name="quantity" label="Stock quantity *" type="number" required /><div className="sm:col-span-2"><Label htmlFor="shortDescription">Short description *</Label><Textarea id="shortDescription" name="shortDescription" required /></div><div className="sm:col-span-2"><Label htmlFor="longDescription">Long description *</Label><Textarea id="longDescription" name="longDescription" rows={5} required /></div></CardContent></Card><Card><CardHeader><CardTitle>Attributes and features</CardTitle></CardHeader><CardContent className="grid gap-4 sm:grid-cols-2"><Field name="tags" label="Tags" placeholder="rudraksha, meditation, gift" /><Field name="size" label="Size" /><Field name="sizeOptions" label="Size options (JSON)" placeholder={'[{"label":"Small","price":499}]'} /><Field name="weight" label="Weight (grams)" type="number" /><Field name="color" label="Color" /><Field name="material" label="Material" /><Field name="estimatedDeliveryTime" label="Estimated delivery" select options={["1-2 Business Days","3-5 Business Days","5-7 Business Days","1-2 Weeks"].map((value) => ({ value, label: value }))} /><Field name="certificateLabel" label="Certificate label" placeholder="Lab Certified" /><label className="flex items-center gap-2 text-sm sm:col-span-2"><input type="checkbox" name="hasCertificate" className="size-4" /> Has certificate</label></CardContent></Card><div className="flex flex-wrap justify-end gap-3"><Button variant="outline" asChild><Link href="/vendor/dashboard">Cancel</Link></Button><Button type="submit">Submit for approval</Button></div></form></main>;
}
function Field({ name, label, type = "text", required, placeholder, select, options }: { name: string; label: string; type?: string; required?: boolean; placeholder?: string; select?: boolean; options?: { value: string; label: string }[] }) { return <div className="flex flex-col gap-2"><Label htmlFor={name}>{label}</Label>{select ? <select id={name} name={name} required={required} defaultValue="" className="h-9 rounded-md border bg-background px-3 text-sm"><option value="">Select…</option>{options?.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : <Input id={name} name={name} type={type} required={required} placeholder={placeholder} min={type === "number" ? "0" : undefined} />}</div>; }
